--[[
    @desc: 增加一个物品
    author:{author}
    time:2020-04-26 16:31:17
    --@itemData:
	--@type: 
    @return:
]]
function MazeBagComponent:Additem(itemData, type)
    if not itemData then return end

    if type == Constants.IDType.MazeItem then
        local isNew = true
        for k, v in pairs(self.itemTab) do
            if checkNumber(v.id) == checkNumber(itemData.goodsId) then
                self.itemTab[k].num = checkNumber(self.itemTab[k].num) + checkNumber(itemData.num)
                isNew = false
                break
            end
        end
        if isNew then
            table.insert(self.itemTab, itemData)
        end
        --if self.itemTab[checkString(itemData.goodsId)] then
        --    self.itemTab[checkString(itemData.goodsId)] = checkNumber(itemData.num) + checkNumber(self.itemTab[checkString(itemData.goodsId)])
        --else
        --    self.itemTab[checkString(itemData.goodsId)] = checkNumber(itemData.num)
        --end
    --圣物和诅咒只会传id
    elseif type == Constants.IDType.Relics then
        table.insert(self.relicsTab, {
            relicId = itemData,
            num = 1
        } )
        --self.relicsTab[checkString(itemData)] = 1
    elseif type == Constants.IDType.Curses then
        table.insert(self.cursesTab, {
            curseId = itemData,
            num = 1
        } )
        --self.cursesTab[checkString(itemData)] = 1
    end
    --Events.Broadcast(Constants.EventNames.MazeBagNumChange, nil)
end

--删除诅咒
function MazeBagComponent:DelCurses(jsonData)
    if not jsonData then
        return
    end
    for k, v in pairs(jsonData) do
        for i, b in pairs(self.cursesTab) do
            if checkNumber(v) == checkNumber(b.curseId) then
                table.removebyvalue(self.cursesTab, b)
            end
        end
        --self.cursesTab[checkString(v)] = nil
    end
    --Events.Broadcast(Constants.EventNames.MazeBagNumChange, nil)
end

--使用一个物品  
function MazeBagComponent:Delitem(itemId, count)
    count = checkNumber(count)
    itemId = checkNumber(itemId)
    for k, v in pairs(self.itemTab) do
        local curCount
        if checkNumber(v.goodsId) == itemId then
            curCount = checkNumber(v.num) - count
            if curCount <= 0 then
                table.removebyvalue(self.itemTab, v)
            else
                self.itemTab[k].num = curCount
            end
        end
    end
    --local curCount = checkNumber(self.itemTab[itemId])
