--获取背包可使用物品的数组
function MazeBagComponent:GetItemArr()
    local t = {}
    for k, v in pairs(self.itemTab) do
        local item = {
            ["id"] = v.goodsId,
            ["num"] = v.num,
            idAreaType = Constants.IDArea.Maze,
        }
        table.insert(t,item)
    end
    return t
end

--获取背包可使用物品的数量
function MazeBagComponent:GetUseItemNum()
    local count = 0
    for k, v in pairs(self.itemTab) do
        count = count + checkNumber(v.num)
    end
    return count
end

--buff 数组
function MazeBagComponent:GetRelicsArr()
    local t = {}
