            ["num"] = v.num,
            idAreaType = Constants.IDArea.Maze,
        }
        table.insert(t,item)
    end
    return t
end

--诅咒数组
function MazeBagComponent:GetCursesArr()
    local t = {}
    for k, v in pairs(self.cursesTab) do
        local item = {
            ["id"] = v.curseId,
            ["num"] = v.num,
            idAreaType = Constants.IDArea.Maze,
        }
        table.insert(t,item)
