function MazeBagComponent:GetTitleIma(titleType)
    if titleType == Constants.IDType.MazeItem then
        return "uiatlas/Maze/MazeMain/maze_main_ico_item.png"
    elseif titleType == Constants.IDType.Relics then
        return "uiatlas/Maze/MazeMain/maze_main_ico_buff.png"
    elseif titleType == Constants.IDType.Curses then
        return "uiatlas/Maze/MazeMain/maze_main_ico_debuff.png"
    end 
    return "uiatlas/Maze/MazeMain/maze_main_ico_item.png"
end

function MazeBagComponent:GetItemShowBg(itemType)
    if itemType == Constants.IDType.MazeItem then
        return "uiatlas/Maze/MazeBag/maze_preview_bg.png"
    elseif itemType == Constants.IDType.Relics then
        return "uiatlas/Maze/MazeBag/maze_bag_bg_buff.png"
    elseif itemType == Constants.IDType.Curses then
        return "uiatlas/Maze/MazeBag/maze_bag_bg_debuff.png"
    end 
    return "uiatlas/Maze/MazeBag/maze_preview_bg.png"
end

return MazeBagComponent